    /**
     * toString() renders options that only have a long name using the long-option
     * prefix ("--"). Here both options lack a short name, so both appear as "--name".
     */
    @Test(timeout = 4000)
    public void toString_rendersLongOptionsWithLongPrefix() throws Throwable {
        OptionGroup optionGroup = new OptionGroup();
        Option longOptionNoDescription = new Option((String) null, (String) null);
        optionGroup.addOption(longOptionNoDescription);
        Option longOptionWithArg = new Option((String) null, "[]", true, (String) null);
        optionGroup.addOption(longOptionWithArg);

        String rendered = optionGroup.toString();

        assertEquals("[--null, --[]]", rendered);
    }

    /**
     * toString() appends the option description (separated by a space) when the
     * description is non-null, even when it is the empty string.
     */
    @Test(timeout = 4000)
    public void toString_appendsEmptyDescriptionWithSpace() throws Throwable {
        OptionGroup optionGroup = new OptionGroup();
        Option longOption = new Option((String) null, (String) null);
        optionGroup.addOption(longOption);
        longOption.setDescription("");

        String rendered = optionGroup.toString();

        assertEquals("[--null ]", rendered);
    }

