    /**
     * setSelected() throws once a different option has already been selected,
     * because the options in a group are mutually exclusive.
     */
    @Test(timeout = 4000)
    public void setSelected_throwsWhenADifferentOptionIsAlreadySelected() throws Throwable {
        OptionGroup optionGroup = new OptionGroup();
        Option firstOption = new Option((String) null, (String) null);
        Option alreadySelectedOption = new Option((String) null, "[]", true, (String) null);
        optionGroup.setSelected(alreadySelectedOption);

        try {
            optionGroup.setSelected(firstOption);
            fail("Expecting exception: Exception");
        } catch (Exception e) {
            // The option 'null' was specified but an option from this group
            // has already been selected: '[]'
            verifyException("org.apache.commons.cli.OptionGroup", e);
        }
    }

